CREATE TYPE "ClientProjectStatus" AS ENUM ('PLANNING','IN_PROGRESS','REVIEW','COMPLETED','ON_HOLD');
CREATE TYPE "InvoiceStatus" AS ENUM ('DRAFT','SENT','PARTIALLY_PAID','PAID','OVERDUE','CANCELLED');
CREATE TYPE "SupportStatus" AS ENUM ('OPEN','IN_PROGRESS','RESOLVED','CLOSED');
CREATE TABLE "Client" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"company" TEXT,"email" TEXT NOT NULL,"phone" TEXT,"password" TEXT,"isActive" BOOLEAN NOT NULL DEFAULT true,"inviteTokenHash" TEXT,"inviteTokenExpires" TIMESTAMP(3),"lastLoginAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Client_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Client_email_key" ON "Client"("email");
CREATE TABLE "ClientProject" ("id" TEXT NOT NULL,"clientId" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT,"status" "ClientProjectStatus" NOT NULL DEFAULT 'PLANNING',"progress" INTEGER NOT NULL DEFAULT 0,"startDate" TIMESTAMP(3),"dueDate" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ClientProject_pkey" PRIMARY KEY ("id"));
CREATE INDEX "ClientProject_clientId_status_idx" ON "ClientProject"("clientId","status");
CREATE TABLE "ClientMilestone" ("id" TEXT NOT NULL,"projectId" TEXT NOT NULL,"title" TEXT NOT NULL,"completed" BOOLEAN NOT NULL DEFAULT false,"dueDate" TIMESTAMP(3),"order" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ClientMilestone_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ClientFile" ("id" TEXT NOT NULL,"projectId" TEXT NOT NULL,"name" TEXT NOT NULL,"url" TEXT NOT NULL,"fileType" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ClientFile_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ClientInvoice" ("id" TEXT NOT NULL,"clientId" TEXT NOT NULL,"number" TEXT NOT NULL,"title" TEXT NOT NULL,"amount" DECIMAL(12,2) NOT NULL,"paid" DECIMAL(12,2) NOT NULL DEFAULT 0,"currency" TEXT NOT NULL DEFAULT 'GHS',"status" "InvoiceStatus" NOT NULL DEFAULT 'DRAFT',"dueDate" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ClientInvoice_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "ClientInvoice_number_key" ON "ClientInvoice"("number");
CREATE INDEX "ClientInvoice_clientId_status_idx" ON "ClientInvoice"("clientId","status");
CREATE TABLE "SupportRequest" ("id" TEXT NOT NULL,"clientId" TEXT NOT NULL,"subject" TEXT NOT NULL,"message" TEXT NOT NULL,"priority" TEXT NOT NULL DEFAULT 'Normal',"status" "SupportStatus" NOT NULL DEFAULT 'OPEN',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "SupportRequest_pkey" PRIMARY KEY ("id"));
CREATE INDEX "SupportRequest_clientId_status_idx" ON "SupportRequest"("clientId","status");
CREATE TABLE "ClientUpdate" ("id" TEXT NOT NULL,"clientId" TEXT NOT NULL,"projectId" TEXT,"title" TEXT NOT NULL,"message" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ClientUpdate_pkey" PRIMARY KEY ("id"));
CREATE INDEX "ClientUpdate_clientId_createdAt_idx" ON "ClientUpdate"("clientId","createdAt");
ALTER TABLE "ClientProject" ADD CONSTRAINT "ClientProject_clientId_fkey" FOREIGN KEY ("clientId") REFERENCES "Client"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ClientMilestone" ADD CONSTRAINT "ClientMilestone_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "ClientProject"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ClientFile" ADD CONSTRAINT "ClientFile_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "ClientProject"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ClientInvoice" ADD CONSTRAINT "ClientInvoice_clientId_fkey" FOREIGN KEY ("clientId") REFERENCES "Client"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "SupportRequest" ADD CONSTRAINT "SupportRequest_clientId_fkey" FOREIGN KEY ("clientId") REFERENCES "Client"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ClientUpdate" ADD CONSTRAINT "ClientUpdate_clientId_fkey" FOREIGN KEY ("clientId") REFERENCES "Client"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ClientUpdate" ADD CONSTRAINT "ClientUpdate_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "ClientProject"("id") ON DELETE CASCADE ON UPDATE CASCADE;
